def check_public():
    for name in ('cosmos-terms.html','cosmos-privacy.html','cosmos-guidelines.html'):
        url='https://ptdtoday.com/'+name
        try:
            req=urllib.request.Request(url,headers={'User-Agent':'COSMOS-safe-legal-activation/1'})
            with urllib.request.urlopen(req,timeout=15) as r:
                data=r.read(100000).decode('utf-8','replace')
                if r.status!=200 or 'COSMOS_LEGAL_VERSION: '+VERSION not in data or '<html' not in data.lower():
                    raise ValueError('policy content version incorrect')
        except Exception as e: raise RuntimeError('Cannot activate: '+url+' is unavailable or old version. '+str(e))
    # This checks the matching backend. It does not activate strict enforcement.
    url='https://ptdtoday-cosmos-life.ptdtoday.workers.dev/api/health'
    try:
        with urllib.request.urlopen(url,timeout=15) as r:
            data=json.load(r)
            if data.get('version')!='cosmos-life-v9.5.5-rights-attestation':
                raise ValueError('Life Worker version differs from COSMOS v9.5.5 rights-safe Worker')
    except Exception as e: raise RuntimeError('Cannot activate: Life Worker not ready. '+str(e))

def main():
    ap=argparse.ArgumentParser();ap.add_argument('--mode',choices=('validate-activate','activate'),required=True)
    mode=ap.parse_args().mode
    source=pathlib.Path('cosmos-next.html')
    if not source.exists():raise SystemExit('ERROR: frontend source missing.')
    data=source.read_bytes(); sha=hashlib.sha256(data).hexdigest()
    if sha==POST_SHA:
        print('Already installed. Check /api/legal/status, D1, and user login before strict enforcement.');return
    if sha!=PRE_SHA:
        raise SystemExit('ERROR: frontend does not exactly match v9.5.3 plus v9.5.5 rights changes; no files changed. Merge against your current code safely.')
    payload=zlib.decompress(base64.b85decode(PAYLOAD))
    if hashlib.sha256(payload).hexdigest()!=POST_SHA:raise SystemExit('ERROR: payload checksum mismatch. No files changed.')
    try:check_public()
    except RuntimeError as e:raise SystemExit('ERROR: '+str(e))
    if mode=='validate-activate':
        print('PASS: live pages and compatible Worker accessible; frontend legal acceptance patch validates. No files changed.');return
    source.write_bytes(payload)
    print('Installed frontend legal agreement UI. Test new + returning accounts BEFORE setting COSMOS_LEGAL_ENFORCEMENT_ENABLED=true.')
if __name__=='__main__':main()
